-- Mots-clés des sous-rubriques des univers (Semrush FR, 11/11/2026) — docs/seo/keywords-sous-rubriques-2026-11.csv
-- Idempotent : met à jour les mesures Semrush sans toucher au statut ni à la page cible.
on conflict (site_id, keyword) do update set volume = excluded.volume, cpc_eur = excluded.cpc_eur, kd = excluded.kd,
  source = excluded.source, refreshed_at = excluded.refreshed_at
where public.keyword_targets.source in ('semrush', 'a_mesurer');
